  if (agent.name === 'copilot') {
    return './.github/skills/ or ~/.copilot/skills/'
  }
  if (DUAL_PATH_AGENTS.has(agent.name)) {
    const homePath = agent.label
    const l = NAME_TO_DIR[agent.name] || agent.name
    const projPath = `./.${l}/skills/`
